/**
 * Retrieves the file extension from a given file name, returning a default value if no extension is found.
 *
 * @param {string} fileName The file name to extract the extension from.
 * @param {string} [deflt=''] The default value to return if no extension is found.
 * @returns {string} The file extension, or the default value if no extension is found.
 */
function getFileExtension(fileName, deflt = '') {
  // Find the last occurrence of a dot (.) in the file name
  const lastDotIndex = fileName.lastIndexOf('.');

  // If a dot is found, return the substring after the dot
  if (lastDotIndex !== -1) {
    return fileName.substring(lastDotIndex + 1);
  }

  // If no dot is found, return the default value
  return deflt;
}

// Example usage:
console.log(getFileExtension('example.txt'));  // Output: txt
console.log(getFileExtension('example'));  // Output: (empty string)
console.log(getFileExtension('example.txt', 'unknown'));  // Output: txt
console.log(getFileExtension('example', 'unknown'));  // Output: unknown

