import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.Optional;

public class DateFinder {

    /**
     * Finds the first date matching the given name and returns it as a ZonedDateTime in the GMT time zone.
     * 
     * @param name the name to search for
     * @return an Optional containing the first matching date, or an empty Optional if no match is found or the date string is invalid
     */
    public static Optional<ZonedDateTime> findDate(String name) {
        // Define the date format to match
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

        // Try to parse the date string
        try {
            // Attempt to parse the date string into a ZonedDateTime
            ZonedDateTime date = ZonedDateTime.parse(name, formatter);

            // If the date is in the GMT time zone, return it as is
            if (date.getZone().equals(ZoneId.of("GMT"))) {
                return Optional.of(date);
            } else {
                // If the date is not in the GMT time zone, convert it to GMT
                return Optional.of(date.withZoneSameInstant(ZoneId.of("GMT")));
            }
        } catch (DateTimeParseException e) {
            // If the date string is invalid, return an empty Optional
            return Optional.empty();
        }
    }

    public static void main(String[] args) {
        System.out.println(findDate("2022-01-01 00:00:00")); // Optional[ZonedDateTime]
        System.out.println(findDate("invalid date")); // Optional.empty
    }
}

