/**
 * Validates the given extension model, checking for overrides of equals and hashCode methods.
 * 
 * @param extensionModel the extension model to validate
 * @param problemsReporter the reporter to report any validation issues
 */
public void validate(ExtensionModel extensionModel, ProblemsReporter problemsReporter) {
    // Check if equals method is overridden
    if (extensionModel.getClass().getDeclaredMethod("equals", Object.class) != null) {
        // Check if equals method is correctly overridden
        if (!isCorrectlyOverridden(extensionModel, "equals", Object.class, problemsReporter)) {
            return;
        }
    }

    // Check if hashCode method is overridden
    if (extensionModel.getClass().getDeclaredMethod("hashCode") != null) {
        // Check if hashCode method is correctly overridden
        if (!isCorrectlyOverridden(extensionModel, "hashCode", null, problemsReporter)) {
            return;
        }
    }

    // If no issues found, report success
    problemsReporter.reportSuccess("Extension model is valid");
}

/**
 * Checks if the given method is correctly overridden in the given class.
 * 
 * @param clazz the class to check
 * @param methodName the name of the method to check
 * @param parameterTypes the parameter types of the method to check
 * @param problemsReporter the reporter to report any validation issues
 * @return true if the method is correctly overridden, false otherwise
 */
private boolean isCorrectlyOverridden(Class<?> clazz, String methodName, Class<?>[] parameterTypes, ProblemsReporter problemsReporter) {
    try {
        // Get the method from the class
        Method method = clazz.getDeclaredMethod(methodName, parameterTypes);

        // Check if the method is correctly overridden
        if (method.getDeclaringClass() != Object.class) {
            // If the method is not correctly overridden, report an issue
            problemsReporter.reportIssue("Method " + methodName + " is not correctly overridden");
            return false;
        }
    } catch (NoSuchMethodException e) {
        // If the method does not exist, report an issue
        problemsReporter.reportIssue("Method " + methodName + " does not exist");
        return false;
    }

    return true;
}
